<?php
function dr_form_value($name, $fallback = '') { return set_value($name, $fallback); }
$grades = array('no_dr' => 'No DR', 'mild_npdr' => 'Mild NPDR', 'moderate_npdr' => 'Moderate NPDR', 'severe_npdr' => 'Severe NPDR', 'pdr' => 'PDR');
$dme = array('no_dme' => 'No DME', 'non_ci_dme' => 'Non-CI DME', 'ci_dme' => 'CI-DME (Clinically Significant)');
$findings = array('microaneurysms','hemorrhages','hard_exudates','cotton_wool_spots','venous_beading','irma','neovascularization','vitreous_hemorrhage','tractional_rd','macular_edema','laser_scars');
?>
