<div class="box dr-form-box"><div class="box-header with-border"><h3 class="box-title"><i class="fa fa-heartbeat text-purple"></i> Diabetes History</h3></div><div class="box-body"><div class="row"><div class="form-group col-sm-4"><label>Diabetes Type</label><select class="form-control" name="diabetes_type"><option value="type1">Type 1</option><option value="type2" selected>Type 2</option><option value="gestational">Gestational</option><option value="other">Other</option></select></div><div class="form-group col-sm-4"><label>Duration of Diabetes</label><input type="number" min="0" class="form-control" name="diabetes_duration" value="<?php echo html_escape(dr_form_value('diabetes_duration',0)); ?>"></div><div class="form-group col-sm-4"><label>HbA1c</label><input type="number" min="0" step="0.1" class="form-control" name="hba1c" value="<?php echo html_escape(dr_form_value('hba1c',7)); ?>"></div></div><div class="row"><div class="form-group col-sm-3"><label>BP Systolic</label><input type="number" min="0" class="form-control" name="bp_systolic" value="<?php echo html_escape(dr_form_value('bp_systolic',120)); ?>"></div><div class="form-group col-sm-3"><label>BP Diastolic</label><input type="number" min="0" class="form-control" name="bp_diastolic" value="<?php echo html_escape(dr_form_value('bp_diastolic',80)); ?>"></div><div class="form-group col-sm-3"><label>Total Cholesterol</label><input type="number" min="0" class="form-control" name="total_cholesterol" value="<?php echo html_escape(dr_form_value('total_cholesterol',200)); ?>"></div><div class="form-group col-sm-3"><label>LDL</label><input type="number" min="0" class="form-control" name="ldl" value="<?php echo html_escape(dr_form_value('ldl',100)); ?>"></div><input type="hidden" name="hdl" value="50"><input type="hidden" name="triglycerides" value="150"><input type="hidden" name="last_hba1c_date" value="<?php echo date('Y-m-d'); ?>"></div></div></div>
